import java.io.*;

record User(String username, String email) implements Serializable {
    private static final long serialVersionUID = 1L;
}

public class SerializationDemo {
    public static void main(String[] args) throws IOException, ClassNotFoundException {
        var user = new User("alice", "alice@example.com");

        // Serialize: write object to file
        try (var out = new ObjectOutputStream(new FileOutputStream("user.ser"))) {
            out.writeObject(user);  // converts object to bytes
        }

        // Deserialize: read object from file
        try (var in = new ObjectInputStream(new FileInputStream("user.ser"))) {
            var restored = (User) in.readObject();  // reconstructs object from bytes
            System.out.println(restored.username());  // prints: alice
        }
    }
}

import java.io.*;

class Customer implements Serializable {
    private static final long serialVersionUID = 1L;  // explicit version control

    private String name;
    private String email;
    private int loyaltyPoints;  // new field added later

    public Customer(String name, String email) {
        this.name = name;
        this.email = email;
        this.loyaltyPoints = 0;  // default for backward compatibility
    }
}

class LegacyCustomer implements Serializable {
    // no explicit serialVersionUID — compiler generates one
    private String name;
    private String email;
    // adding ANY field breaks all existing serialized objects
}

import java.io.*;
import java.net.*;

public class VulnerableServer {
    public void handleRequest(Socket socket) throws Exception {
        // DANGEROUS: deserializing bytes from untrusted client
        var in = new ObjectInputStream(socket.getInputStream());
        var obj = in.readObject();  // attacker controls this byte stream!

        // Even if you never cast obj or call methods on it,
        // gadget chains can execute during readObject()
    }
}

// Safer alternative: use JSON instead
public class SafeServer {
    private final ObjectMapper mapper = new ObjectMapper();

    public void handleRequest(Socket socket) throws Exception {
        var json = new String(socket.getInputStream().readAllBytes());
        var dto = mapper.readValue(json, RequestDTO.class);  // only data, no code execution
    }
}
